mapper.select:
SELECT COUNT(*) FROM finance_review_task t
WHERE 1=1

    AND t.dept_id IN
    #{id}

AND t.create_time >= #{startDate}
AND t.create_time <= #{endDate}

SELECT COUNT(*) FROM finance_review_task t
WHERE t.status = 'DONE'

    AND t.dept_id IN
    #{id}

AND t.create_time >= #{startDate}
AND t.create_time <= #{endDate}

SELECT COUNT(*) FROM finance_review_task t
WHERE t.status IN ('PENDING', 'IN_PROGRESS')
  AND t.task_date < CURDATE()

    AND t.dept_id IN
    #{id}

AND t.create_time >= #{startDate}
AND t.create_time <= #{endDate}

SELECT AVG(resp.first_response_hours)
FROM (
    SELECT TIMESTAMPDIFF(HOUR, MIN(t.create_time), MIN(l.action_time)) AS first_response_hours
    FROM finance_review_task t
    INNER JOIN finance_review_task_log l ON l.task_id = t.task_id
    WHERE l.action_type = 'IN_PROGRESS'

        AND t.dept_id IN
        #{id}

    AND t.create_time >= #{startDate}
    AND t.create_time <= #{endDate}
    GROUP BY t.task_id
) resp

SELECT AVG(TIMESTAMPDIFF(HOUR, t.create_time, t.update_time))
FROM finance_review_task t
WHERE t.status = 'DONE'

    AND t.dept_id IN
    #{id}

AND t.create_time >= #{startDate}
AND t.create_time <= #{endDate}

SELECT COUNT(*) FROM finance_review_task t
WHERE t.status = 'DONE'
  AND NOT EXISTS (
      SELECT 1 FROM finance_review_task_log l
      WHERE l.task_id = t.task_id
        AND l.action_type = 'DONE'
        AND l.handler_note IS NOT NULL
        AND l.handler_note != ''
  )

    AND t.dept_id IN
    #{id}

AND t.create_time >= #{startDate}
AND t.create_time <= #{endDate}
